const webhookData = $('Webhook').first().json.body;

// Create clean object with basic fields
const newData = {
  Fecha: webhookData.fecha,
  Ciclo: webhookData.ciclo,
  Lleno: webhookData.lleno,
  Grupo: webhookData.grupo,
  Tipo: webhookData.tipo
};

// Add dynamic columns for each vendedor
if (webhookData.vendedores && Array.isArray(webhookData.vendedores)) {
  for (const vendedor of webhookData.vendedores) {
    newData[vendedor.nombre] = vendedor.contador;
  }
}

return [{ json: newData }];

const webhookData = $('Webhook').first().json.body;

const updateData = {
  row_number: webhookData.row_number,
  [webhookData.vendedor]: webhookData.contador
};

return [{ json: updateData }];

const webhookData = $('Webhook').first().json.body;

// Create clean object for marcar_lleno
const updateData = {
  row_number: webhookData.rowId,
  Lleno: true
};

// Add all vendedor counters from the webhook data
for (const [key, value] of Object.entries(webhookData)) {
  // Skip system fields, keep only vendedor counters
  if (!['query', 'rowId', 'row_number', 'Fecha', 'Ciclo', 'Lleno', 'Tipo', 'Grupo'].includes(key)) {
    updateData[key] = value;
  }
}

return [{ json: updateData }];
